-- CampBuddy — Zonen für die Region CH.
-- Ausführen: Supabase-Projekt -> SQL Editor -> Inhalt einfügen -> Run.
--
-- 382 Flächen, Geometrie aus OpenStreetMap (ODbL), auf ~40 m vereinfacht.
-- 345 davon mit regelbasiert abgeleiteter Einstufung, 37 ausdrücklich 'unknown'.
--
-- KEINE dieser Einstufungen ist geprüft: alle tragen review_status 'entwurf'
-- und kein Prüfdatum. Abgeleitet wird nur, wo OSM ein eindeutiges Signal
-- liefert, und der Fehler geht immer in die sichere Richtung (verboten).
-- Teil 1 von 2.

begin;
on conflict (id) do update set region = excluded.region, name = excluded.name, status = excluded.status, tent_allowed = excluded.tent_allowed, vehicle_allowed = excluded.vehicle_allowed, fire_allowed = excluded.fire_allowed, conditions = excluded.conditions, notes = excluded.notes, source = excluded.source, source_url = excluded.source_url, review_status = excluded.review_status, last_verified = excluded.last_verified, geometry = excluded.geometry, updated_at = now();
commit;
